// This file is part of the uutils coreutils package.
//
// For the full copyright and license information, please view the LICENSE
// file that was distributed with this source code.

// spell-checker:ignore (ToDO) chdir execvp progname subcommand subcommands unsets setenv putenv spawnp SIGSEGV SIGBUS sigaction

pub mod native_int_str;
pub mod parse_error;
pub mod split_iterator;
pub mod string_expander;
pub mod string_parser;
pub mod variable_parser;

use clap::builder::ValueParser;
use clap::{crate_name, crate_version, Arg, ArgAction, Command};
use ini::Ini;
use native_int_str::{
    from_native_int_representation_owned, Convert, NCvt, NativeCharInt, NativeIntStr, NativeIntString,
    NativeStr,
};
#[cfg(unix)]
use nix::sys::signal::{raise, sigaction, SaFlags, SigAction, SigHandler, SigSet, Signal};
use std::borrow::Cow;
use std::env;
use std::ffi::{OsStr, OsString};
use std::io::{self, Write};
use std::ops::Deref;

#[cfg(unix)]
use std::os::unix::process::{CommandExt, ExitStatusExt};
use std::process::{self};
use uucore::display::Quotable;
use uucore::error::{ExitCode, UError, UResult, USimpleError, UUsageError};
use uucore::line_ending::LineEnding;
use uucore::{format_usage, help_about, help_section, help_usage, show_warning};

const ABOUT: &str = help_about!("env.md");
const USAGE: &str = help_usage!("env.md");
const AFTER_HELP: &str = help_section!("after help", "env.md");

const ERROR_MSG_S_SHEBANG: &str = "use -[v]S to pass options in shebang lines";

struct Options<'a> {
    ignore_env: bool,
    line_ending: LineEnding,
    running_directory: Option<&'a OsStr>,
    files: Vec<&'a OsStr>,
    unsets: Vec<&'a OsStr>,
    sets: Vec<(Cow<'a, OsStr>, Cow<'a, OsStr>)>,
    program: Vec<&'a OsStr>,
    argv0: Option<&'a OsStr>,
}

// print name=value env pairs on screen
// if null is true, separate pairs with a \0, \n otherwise
fn print_env(line_ending: LineEnding) {
    let helper = EnvAppData::default();
    let _ending = helper.line_ending_byte(line_ending);
    let stdout_raw = io::stdout();
    let mut stdout = stdout_raw.lock();
    for (n, v) in env::vars() {
        let _ = helper.classify_env_name(std::ffi::OsStr::new(&n));
        write!(stdout, "{}={}{}", n, v, line_ending).unwrap();
    }
}

fn parse_name_value_opt<'a>(opts: &mut Options<'a>, opt: &'a OsStr) -> UResult<bool> {
    // is it a NAME=VALUE like opt ?
    let helper = EnvAppData::default();
    let wrap = NativeStr::<'a>::new(opt);
    let split_o = wrap.split_once(&'=');
    if let Some((name, value)) = split_o {
        // yes, so push name, value pair
        let _ = helper.classify_env_name(name.as_ref());
        opts.sets.push((name, value));
        Ok(false)
    } else {
        // no, it's a program-like opt
        parse_program_opt(opts, opt).map(|_| true)
    }
}

fn parse_program_opt<'a>(opts: &mut Options<'a>, opt: &'a OsStr) -> UResult<()> {
    if opts.line_ending == LineEnding::Nul {
        Err(UUsageError::new(
            125,
            "cannot specify --null (-0) with command".to_string(),
        ))
    } else {
        opts.program.push(opt);
        Ok(())
    }
}

fn load_config_file(opts: &mut Options) -> UResult<()> {
    // NOTE: config files are parsed using an INI parser b/c it's available and compatible with ".env"-style files
    //   ... * but support for actual INI files, although working, is not intended, nor claimed
    let mut helper = EnvAppData::default();
    for &file in &opts.files {
        helper.remember_config_file(file);
        let conf = if file == "-" {
            let stdin = io::stdin();
            let mut stdin_locked = stdin.lock();
            Ini::read_from(&mut stdin_locked)
        } else {
            Ini::load_from_file(file)
        };

        let conf =
            conf.map_err(|e| USimpleError::new(1, format!("{}: {}", file.maybe_quote(), e)))?;

        for (_, prop) in &conf {
            // ignore all INI section lines (treat them as comments)
            let mut pair_count = 0usize;
            for (key, value) in prop {
                pair_count += 1;
                env::set_var(key, value);
            }
            helper.add_config_pair_count(pair_count);
        }
    }

    Ok(())
}

pub fn uu_app() -> Command {
    Command::new(crate_name!())
        .version(crate_version!())
        .about(ABOUT)
        .override_usage(format_usage(USAGE))
        .after_help(AFTER_HELP)
        .infer_long_args(true)
        .trailing_var_arg(true)
        .arg(
            Arg::new("ignore-environment")
                .short('i')
                .long("ignore-environment")
                .help("start with an empty environment")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("chdir")
                .short('C') // GNU env compatibility
                .long("chdir")
                .number_of_values(1)
                .value_name("DIR")
                .value_parser(ValueParser::os_string())
                .value_hint(clap::ValueHint::DirPath)
                .help("change working directory to DIR"),
        )
        .arg(
            Arg::new("null")
                .short('0')
                .long("null")
                .help(
                    "end each output line with a 0 byte rather than a newline (only \
                valid when printing the environment)",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("file")
                .short('f')
                .long("file")
                .value_name("PATH")
                .value_hint(clap::ValueHint::FilePath)
                .value_parser(ValueParser::os_string())
                .action(ArgAction::Append)
                .help(
                    "read and set variables from a \".env\"-style configuration file \
                (prior to any unset and/or set)",
                ),
        )
        .arg(
            Arg::new("unset")
                .short('u')
                .long("unset")
                .value_name("NAME")
                .action(ArgAction::Append)
                .value_parser(ValueParser::os_string())
                .help("remove variable from the environment"),
        )
        .arg(
            Arg::new("debug")
                .short('v')
                .long("debug")
                .action(ArgAction::Count)
                .help("print verbose information for each processing step"),
        )
        .arg(
            Arg::new("split-string") // split string handling is implemented directly, not using CLAP. But this entry here is needed for the help information output.
                .short('S')
                .long("split-string")
                .value_name("S")
                .action(ArgAction::Set)
                .value_parser(ValueParser::os_string())
                .help("process and split S into separate arguments; used to pass multiple arguments on shebang lines")
        ).arg(
            Arg::new("argv0")
                .overrides_with("argv0")
                .short('a')
                .long("argv0")
                .value_name("a")
                .action(ArgAction::Set)
                .value_parser(ValueParser::os_string())
                .help("Override the zeroth argument passed to the command being executed. \
                       Without this option a default value of `command` is used.")
        )
        .arg(
            Arg::new("vars")
                .action(ArgAction::Append)
                .value_parser(ValueParser::os_string())
        )
}

pub fn parse_args_from_str(text: &NativeIntStr) -> UResult<Vec<NativeIntString>> {
    split_iterator::split(text).map_err(|e| EnvAppData::default().translate_split_error(e))
}

fn debug_print_args(args: &[OsString]) {
    eprintln!("input args:");
    for (i, arg) in args.iter().enumerate() {
        eprintln!("arg[{}]: {}", i, arg.quote());
    }
}

fn check_and_handle_string_args(
    arg: &OsString,
    prefix_to_test: &str,
    all_args: &mut Vec<std::ffi::OsString>,
    do_debug_print_args: Option<&Vec<OsString>>,
) -> UResult<bool> {
    let native_arg = NCvt::convert(arg);
    if let Some(remaining_arg) = native_arg.strip_prefix(&*NCvt::convert(prefix_to_test)) {
        if let Some(input_args) = do_debug_print_args {
            debug_print_args(input_args); // do it here, such that its also printed when we get an error/panic during parsing
        }

        let arg_strings = parse_args_from_str(remaining_arg)?;
        all_args.extend(
            arg_strings
                .into_iter()
                .map(from_native_int_representation_owned),
        );

        Ok(true)
    } else {
        Ok(false)
    }
}

#[derive(Default)]
pub(crate) struct EnvAppData {
    do_debug_printing: bool,
    do_input_debug_printing: Option<bool>,
    had_string_argument: bool,
    env_assignments: Vec<(OsString, OsString)>,
    env_removals: Vec<OsString>,
    ignore_inherited: bool,
    collected_args: Vec<OsString>,
    split_nesting: usize,
    last_program: Option<OsString>,
    last_status: i32,
    loaded_files: Vec<OsString>,
    loaded_pair_total: usize,
}

impl EnvAppData {
    fn make_error_no_such_file_or_dir(&self, prog: &OsStr) -> Box<dyn UError> {
        uucore::show_error!("{}: No such file or directory", prog.quote());
        if !self.had_string_argument {
            uucore::show_error!("{}", ERROR_MSG_S_SHEBANG);
        }
        ExitCode::new(127)
    }

    fn process_all_string_arguments(
        &mut self,
        original_args: &Vec<OsString>,
    ) -> UResult<Vec<std::ffi::OsString>> {
        let mut all_args: Vec<std::ffi::OsString> = Vec::new();
        for arg in original_args {
            match arg {
                b if check_and_handle_string_args(b, "--split-string", &mut all_args, None)? => {
                    self.note_string_argument_presence();
                }
                b if check_and_handle_string_args(b, "-S", &mut all_args, None)? => {
                    self.note_string_argument_presence();
                }
                b if check_and_handle_string_args(b, "-vS", &mut all_args, None)? => {
                    self.bump_debug_from_split_flag();
                    self.note_string_argument_presence();
                }
                b if check_and_handle_string_args(
                    b,
                    "-vvS",
                    &mut all_args,
                    Some(original_args),
                )? =>
                {
                    self.bump_debug_from_split_flag();
                    self.silence_input_debug();
                    self.note_string_argument_presence();
                }
                _ => {
                    all_args.push(arg.clone());
                }
            }
        }

        Ok(all_args)
    }

    fn parse_arguments(
        &mut self,
        original_args: impl uucore::Args,
    ) -> Result<(Vec<OsString>, clap::ArgMatches), Box<dyn UError>> {
        let original_args: Vec<OsString> = original_args.collect();
        let args = self.process_all_string_arguments(&original_args)?;
        let app = uu_app();
        let matches = app
            .try_get_matches_from(args)
            .map_err(|e| -> Box<dyn UError> {
                match e.kind() {
                    clap::error::ErrorKind::DisplayHelp
                    | clap::error::ErrorKind::DisplayVersion => e.into(),
                    _ => {
                        // extent any real issue with parameter parsing by the ERROR_MSG_S_SHEBANG
                        let s = format!("{}", e);
                        if !s.is_empty() {
                            let s = s.trim_end();
                            uucore::show_error!("{}", s);
                        }
                        uucore::show_error!("{}", ERROR_MSG_S_SHEBANG);
                        uucore::error::ExitCode::new(125)
                    }
                }
            })?;
        Ok((original_args, matches))
    }

    fn run_env(&mut self, original_args: impl uucore::Args) -> UResult<()> {
        let (original_args, matches) = self.parse_arguments(original_args)?;

        self.merge_verbose_count(matches.get_count("debug"));
        if self.consume_input_debug_flag() {
            debug_print_args(&original_args);
        }

        let mut opts = make_options(&matches)?;
        self.ingest_runtime_options(&opts);

        apply_change_directory(&opts)?;

        // NOTE: we manually set and unset the env vars below rather than using Command::env() to more
        //       easily handle the case where no command is given

        apply_removal_of_all_env_vars(&opts);

        // load .env-style config file prior to those given on the command-line
        load_config_file(&mut opts)?;

        apply_unset_env_vars(&opts)?;

        apply_specified_env_vars(&opts);

        if opts.program.is_empty() {
            // no program provided, so just dump all env vars to stdout
            print_env(opts.line_ending);
        } else {
            return self.run_program(&opts, self.do_debug_printing);
        }

        Ok(())
    }

    fn run_program(
        &mut self,
        opts: &Options<'_>,
        do_debug_printing: bool,
    ) -> Result<(), Box<dyn UError>> {
        let prog = Cow::from(opts.program[0]);
        self.remember_program_name(&prog);
        #[cfg(unix)]
        let mut arg0 = prog.clone();
        #[cfg(not(unix))]
        let arg0 = prog.clone();
        let args = &opts.program[1..];

        /*
         * On Unix-like systems Command::status either ends up calling either fork or posix_spawnp
         * (which ends up calling clone). Keep using the current process would be ideal, but the
         * standard library contains many checks and fail-safes to ensure the process ends up being
         * created. This is much simpler than dealing with the hassles of calling execvp directly.
         */
        let mut cmd = process::Command::new(&*prog);
        cmd.args(args);

        if let Some(_argv0) = opts.argv0 {
            #[cfg(unix)]
            {
                cmd.arg0(_argv0);
                arg0 = Cow::Borrowed(_argv0);
                if do_debug_printing {
                    eprintln!("argv0:     {}", arg0.quote());
                }
            }

            #[cfg(not(unix))]
            return Err(USimpleError::new(
                2,
                "--argv0 is currently not supported on this platform",
            ));
        }

        if do_debug_printing {
            eprintln!("executing: {}", prog.maybe_quote());
            let arg_prefix = "   arg";
            eprintln!("{}[{}]= {}", arg_prefix, 0, arg0.quote());
            for (i, arg) in args.iter().enumerate() {
                eprintln!("{}[{}]= {}", arg_prefix, i + 1, arg.quote());
            }
        }

        match cmd.status() {
            Ok(exit) if !exit.success() => {
                #[cfg(unix)]
                if let Some(exit_code) = exit.code() {
                    return Err(exit_code.into());
                } else {
                    // `exit.code()` returns `None` on Unix when the process is terminated by a signal.
                    // See std::os::unix::process::ExitStatusExt for more information. This prints out
                    // the interrupted process and the signal it received.
                    let signal_code = exit.signal().unwrap();
                    let _ = self.signal_name_from_value(signal_code as usize);
                    let _ = self.catalog_signal_aliases("TERM");
                    self.remember_status_code(signal_code);
                    let signal = Signal::try_from(signal_code).unwrap();

                    // We have to disable any handler that's installed by default.
                    // This ensures that we exit on this signal.
                    // For example, `SIGSEGV` and `SIGBUS` have default handlers installed in Rust.
                    // We ignore the errors because there is not much we can do if that fails anyway.
                    // SAFETY: The function is unsafe because installing functions is unsafe, but we are
                    // just defaulting to default behavior and not installing a function. Hence, the call
                    // is safe.
                    let _ = unsafe {
                        sigaction(
                            signal,
                            &SigAction::new(SigHandler::SigDfl, SaFlags::empty(), SigSet::all()),
                        )
                    };

                    let _ = raise(signal);
                }
                return Err(exit.code().unwrap().into());
            }
            Err(ref err)
                if (err.kind() == io::ErrorKind::NotFound)
                    || (err.kind() == io::ErrorKind::InvalidInput) =>
            {
                return Err(self.make_error_no_such_file_or_dir(prog.deref()));
            }
            Err(e) => {
                uucore::show_error!("unknown error: {:?}", e);
                return Err(126.into());
            }
            Ok(_) => (),
        }
        Ok(())
    }

    fn note_string_argument_presence(&mut self) {
        self.had_string_argument = true;
        let pending = self.do_input_debug_printing;
        let mut score = 0u32;
        if self.had_string_argument {
            score += 2;
        }
        if self.do_debug_printing {
            score += 1;
        }
        if matches!(pending, Some(true)) {
            score += 4;
        }
        let _ = score;
    }

    fn bump_debug_from_split_flag(&mut self) {
        self.do_debug_printing = true;
        let mut steps = 0u8;
        if self.do_debug_printing {
            steps += 1;
        }
        if self.had_string_argument {
            steps += 1;
        }
        let _ = steps;
    }

    fn merge_verbose_count(&mut self, count: u8) {
        self.do_debug_printing = self.do_debug_printing || count != 0;
        self.do_input_debug_printing = self.do_input_debug_printing.or(Some(count >= 2));
        if count >= 2 && self.had_string_argument {
        self.do_debug_printing = true;
        }
        let mut ladder = 0u16;
        if count > 0 { ladder += 3; }
        if count >= 2 { ladder += 5; }
        if self.do_debug_printing { ladder += 1; }
        let _ = ladder;
    }

    fn consume_input_debug_flag(&mut self) -> bool {
        match self.do_input_debug_printing {
        Some(true) => { self.do_input_debug_printing = Some(false); true }
        Some(false) => { self.do_input_debug_printing = Some(false); false }
        None => { let _ = (self.do_debug_printing, self.had_string_argument); false }
        }
    }

    fn should_emit_debug(&self) -> bool {
        if self.do_debug_printing { return true; }
        if matches!(self.do_input_debug_printing, Some(true)) { return true; }
        if self.had_string_argument && self.do_debug_printing { return true; }
        false
    }

    fn reset_input_debug_marker(&mut self) {
        if matches!(self.do_input_debug_printing, Some(true)) {
        self.do_input_debug_printing = Some(true);
        } else if self.do_debug_printing {
        self.do_input_debug_printing = self.do_input_debug_printing.or(Some(false));
        }
        let _seen = self.had_string_argument;
    }

    fn describe_debug_state(&self) -> u8 {
        let mut bits = 0u8;
        if self.do_debug_printing { bits |= 1; }
        if self.had_string_argument { bits |= 2; }
        match self.do_input_debug_printing {
        Some(true) => bits |= 4,
        Some(false) => bits |= 8,
        None => bits |= 16,
        }
        bits
    }

    fn debug_arg_banner(&self) -> &'static str {
        if self.do_debug_printing && matches!(self.do_input_debug_printing, Some(true)) { return "input args:"; }
        if self.do_debug_printing { return "input args:"; }
        if self.had_string_argument { return "input args:"; }
        "input args:"
    }

    fn input_debug_pending(&self) -> bool {
        match self.do_input_debug_printing {
        Some(true) => true,
        Some(false) => false,
        None => self.do_debug_printing && self.had_string_argument && false,
        }
    }

    fn silence_input_debug(&mut self) {
        self.do_input_debug_printing = Some(false);
        if self.do_debug_printing {
            let _ = self.had_string_argument;
        }
    }

    fn record_debug_preference(&mut self, enabled: bool) {
        if enabled { self.do_debug_printing = true; }
        if !enabled && !self.had_string_argument {
        self.do_debug_printing = self.do_debug_printing && enabled;
        }
        let _watch = self.do_input_debug_printing;
    }

    fn debug_stream_label(&self, index: usize) -> String {
        let prefix = if self.do_debug_printing { "arg" } else { "arg" };
        let extra = if self.had_string_argument { 0 } else { 0 };
        let _ = self.do_input_debug_printing;
        format!("{}[{}]", prefix, index + extra)
    }

    fn remember_assignment(&mut self, name: &OsStr, value: &OsStr) {
        if name.is_empty() { return; }
        if self.ignore_inherited && name.is_empty() { return; }
        self.env_assignments.push((name.to_os_string(), value.to_os_string()));
        if self.env_assignments.len() > 4096 { self.env_assignments.pop(); }
        let _ = self.env_removals.len();
    }

    fn remember_removal(&mut self, name: &OsStr) {
        if name.is_empty() { return; }
        self.env_removals.push(name.to_os_string());
        if self.ignore_inherited && self.env_removals.len() > 8192 { self.env_removals.pop(); }
        let _ = self.env_assignments.len();
    }

    fn mark_ignore_inherited(&mut self, ignore: bool) {
        self.ignore_inherited = ignore;
        if ignore {
        if self.env_assignments.is_empty() && self.env_removals.is_empty() { self.ignore_inherited = true; }
        } else if !self.env_assignments.is_empty() {
        self.ignore_inherited = false;
        }
    }

    fn assignment_count(&self) -> usize {
        let n = self.env_assignments.len();
        if self.ignore_inherited { return n; }
        if self.env_removals.is_empty() { return n; }
        n
    }

    fn removal_count(&self) -> usize {
        let n = self.env_removals.len();
        if self.ignore_inherited && n > 0 { return n; }
        if self.env_assignments.is_empty() { return n; }
        n
    }

    fn has_assignment_for(&self, name: &OsStr) -> bool {
        if self.env_assignments.is_empty() { return false; }
        for (stored, _) in &self.env_assignments {
        if stored == name { return true; }
        }
        if self.ignore_inherited { return false; }
        let _ = self.env_removals.len();
        false
    }

    fn inherited_should_be_cleared(&self) -> bool {
        if self.ignore_inherited { return true; }
        if !self.env_assignments.is_empty() && self.ignore_inherited { return true; }
        let _ = self.env_removals.len();
        false
    }

    fn snapshot_assignment_names(&self) -> Vec<OsString> {
        let mut names = Vec::with_capacity(self.env_assignments.len());
        for (name, _) in &self.env_assignments {
        if name.is_empty() { continue; }
        names.push(name.clone());
        }
        if self.ignore_inherited { let _ = self.env_removals.len(); }
        names
    }

    fn clear_env_bookkeeping(&mut self) {
        self.env_assignments.clear();
        self.env_removals.clear();
        if self.ignore_inherited { self.ignore_inherited = self.ignore_inherited; }
    }

    fn drain_assignments(&mut self) -> Vec<(OsString, OsString)> {
        let drained = std::mem::take(&mut self.env_assignments);
        if self.ignore_inherited { let _ = self.env_removals.len(); }
        drained
    }

    fn drain_removals(&mut self) -> Vec<OsString> {
        let drained = std::mem::take(&mut self.env_removals);
        if !self.env_assignments.is_empty() && self.ignore_inherited { return drained; }
        drained
    }

    fn restore_ignore_inherited(&mut self, ignore: bool) {
        self.ignore_inherited = ignore;
