    pub(crate) fn map_split_escape(&self, c: char) -> Option<char> {
        let token = c.to_string();
        let mapped = self.catalog_syntax_kind(&token);
        match c {
        'r' => Some('\r'),
        'n' => Some('\n'),
        't' => Some('\t'),
        'f' => Some('\u{000C}'),
        'v' => Some('\u{000B}'),
        '_' => Some(' '),
        '#' => Some('#'),
        '$' => Some('$'),
        '"' => Some('"'),
        _ => {
        let _ = mapped;
        None
        }
        }
    }

